(()=>{function applyBalance(){let p;try{p=JSON.parse(localStorage.getItem('ticket.active-profile.v2')||'null')}catch{}if(!p)return;const safe=v=>String(v||'default').replace(/[^a-zA-Z0-9_-]/g,'').slice(0,80)||'default';const ns=safe(p.id||p.cpfHash?.slice(0,24)||'default');const k=`ticket.balance-settings.v1.${ns}`;let x={};try{x=JSON.parse(localStorage.getItem(k)||'{}')||{}}catch{}if(x.referenceDate==='2026-08-12'&&Number(x.minutes)===690)return;localStorage.setItem(k,JSON.stringify({...x,minutes:690,type:'positive',referenceDate:'2026-08-12',note:'Saldo oficial do banco de horas: +11h30 até 12/08/2026.',updatedAt:new Date().toISOString()}));sessionStorage.setItem('ticket.balance.fix.reload','1')}applyBalance();function enhance(){const m=document.querySelector('#absenceModal');if(!m||m.dataset.finalFix)return;m.dataset.finalFix='1';const photo=document.querySelector('#absencePhoto'),preview=document.querySelector('#absencePreview');if(!photo||!preview)return;const box=photo.closest('.absence-photo');const c=document.createElement('div');c.className='absence-camera-controls';c.innerHTML='<button type="button" id="absenceAlbum">▧<small>Abrir álbum</small></button><button type="button" id="absenceShot" class="shot"></button><button type="button" id="absenceFlip">↻<small>Virar câmera</small></button><button type="button" id="absenceOpen" class="open">▣ &nbsp; Abrir câmera</button>';box.after(c);const album=document.createElement('input');album.type='file';album.accept='image/*';album.hidden=true;m.appendChild(album);const use=f=>{if(!f)return;try{const d=new DataTransfer();d.items.add(f);photo.files=d.files}catch{}if(preview.dataset.url)URL.revokeObjectURL(preview.dataset.url);const u=URL.createObjectURL(f);preview.src=u;preview.dataset.url=u;preview.classList.add('show')};album.onchange=e=>use(e.target.files?.[0]);document.querySelector('#absenceAlbum').onclick=()=>album.click();document.querySelector('#absenceOpen').onclick=()=>photo.click();document.querySelector('#absenceShot').onclick=()=>photo.click();document.querySelector('#absenceFlip').onclick=()=>photo.click()}new MutationObserver(enhance).observe(document.body,{childList:true,subtree:true});enhance()})();